 USE tmp;
-- use ctMigration ;
drop table if exists TMP_COMPANY_SG;

CREATE TABLE TMP_COMPANY_SG 
(
    UUID	VARCHAR(512),
    COMPANY_NAME	VARCHAR(512),
    ACCN_ID	VARCHAR(512),
    EPOD VARCHAR(35),
    PRIMARY KEY (UUID)
)ENGINE=InnoDB AUTO_INCREMENT=2647 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE `TMP_COMPANY_SG` 
ADD UNIQUE INDEX `TMP_COMPANY_SG_ACCN_ID_UNIQUE` (`ACCN_ID` ASC);

ALTER TABLE `TMP_COMPANY_SG` 
ADD UNIQUE INDEX `TMP_COMPANY_SG_UUID_UNIQUE` (`UUID` ASC);








